  ('499d913d-7b44-4968-80e7-479f817ed6d8', 'e7f8a9b0-1c2d-4e23-8f23-3a4b5c6d7e43', '9429a6f3-5ce2-48da-a3d1-2ba6448060c8', 'subtopic'::public.curated_course_node_type, 'Platform story judgment', 'Students learn to decide which medium best serves the evidence, audience, scene, and reporting goal.', 0),
