set
  title = 'Multimedia Journalism',
  goal = 'Multimedia Journalism',
  summary = 'Students report, produce, edit, publish, and evaluate multimedia journalism across text, audio, video, photography, graphics, mobile, social, and CMS-based web packages.',
  data = $mmjjson${"slug": "multimedia-journalism", "title": "Multimedia Journalism", "description": "Students report, produce, edit, publish, and evaluate multimedia journalism across text, audio, video, photography, graphics, mobile, social, and CMS-based web packages.", "topics": [{"id": "9429a6f3-5ce2-48da-a3d1-2ba6448060c8", "type": "topic", "title": "Storytelling Across Platforms", "description": "Multimedia journalism starts with choosing the right form for the story. Students learn to match reporting material to text, audio, video, photography, graphics, social, and interactive formats.", "children": [{"id": "499d913d-7b44-4968-80e7-479f817ed6d8", "type": "subtopic", "title": "Platform story judgment", "children": [{"id": "24e7b94f-b9fa-4fad-8d39-4012d6e4aa1a", "type": "concept", "title": "text-first, audio-first, video-first, visual-first, and interactive-first stories"}, {"id": "7158bb29-7f79-4481-a836-28ed4385789c", "type": "concept", "title": "audience context and distribution path"}, {"id": "30fea949-9ca7-44cf-ad05-02d47c978b3f", "type": "concept", "title": "news, feature, explainer, and service formats"}], "description": "Students learn to decide which medium best serves the evidence, audience, scene, and reporting goal."}, {"id": "cd421488-4c6e-469f-8929-1699767378f3", "type": "subtopic", "title": "Storyboarding and package architecture", "children": [{"id": "4e2aa366-0a35-4911-93b4-9653eaf39eec", "type": "concept", "title": "story maps and asset lists"}, {"id": "bd1d0542-5a08-4651-a7a7-96d96816f66f", "type": "concept", "title": "scene planning and sequence"}, {"id": "1f489304-c153-44fd-8a4f-1acf3a9cdf23", "type": "concept", "title": "handoffs between text, visuals, audio, and graphics"}], "description": "Students plan multimedia packages before production so each element has a clear editorial job."}, {"id": "585fb6cf-d198-4e62-b67b-b5ca8655b5fd", "type": "subtopic", "title": "Ethics across media", "children": [{"id": "b6c2512e-6e85-4314-856c-a7c076a24c1e", "type": "concept", "title": "staging and reenactment boundaries"}, {"id": "dcb6b09a-9d3d-47f8-a0f5-98bf229c343d", "type": "concept", "title": "editing context and fairness"}, {"id": "bb2054e5-88b5-44ec-b4d4-2cf11cd914e1", "type": "concept", "title": "caption, credit, and disclosure practices"}], "description": "Students consider how form choices affect truthfulness, consent, representation, and audience interpretation."}]}, {"id": "3920b735-41e3-49db-904d-fb3e7a4f812e", "type": "topic", "title": "Audio Recording and Editing", "description": "Audio gives journalism intimacy, atmosphere, and voice. Students learn to gather clean sound, conduct audio-aware interviews, and edit stories that are clear, accurate, and listenable.", "children": [{"id": "a20b47d2-6561-4cb8-923c-58081eb9115e", "type": "subtopic", "title": "Field recording fundamentals", "children": [{"id": "f538f1a2-3be8-4f0d-a903-4b47417c3b14", "type": "concept", "title": "microphone choice and placement"}, {"id": "242fec71-abac-40b4-9ca0-c9972a5f2dd0", "type": "concept", "title": "levels, room tone, and natural sound"}, {"id": "8ffc6e7c-9ef3-44bb-aa7b-23afaf74944d", "type": "concept", "title": "backup recording and file management"}], "description": "Students learn the practical habits that make audio usable under real reporting conditions."}, {"id": "327e8d93-b4b6-4a36-ae43-f7f59770ec1a", "type": "subtopic", "title": "Writing and interviewing for the ear", "children": [{"id": "4fc0e070-acd3-4cf4-a26b-fb6740bd0926", "type": "concept", "title": "host narration and tracking"}, {"id": "17000039-d6e8-4c0e-9535-8319cf829296", "type": "concept", "title": "actualities and tape selection"}, {"id": "f12f6e77-7d3f-4a8f-a132-c8c888157999", "type": "concept", "title": "audio interview preparation"}], "description": "Students practice scripting and interviewing in ways that sound conversational while remaining precise."}, {"id": "61ecb705-45d5-46ec-86cc-27c292dd6c38", "type": "subtopic", "title": "Audio editing and mixing", "children": [{"id": "52ee331c-07e0-49bf-9b79-20b7930ec8e5", "type": "concept", "title": "cuts, fades, and pacing"}, {"id": "f54acb5c-8523-4997-9c97-6abdd6921cb0", "type": "concept", "title": "noise reduction and loudness"}, {"id": "ef34aea2-acef-4dee-b227-3cbaec25c9c9", "type": "concept", "title": "transcripts, accessibility, and corrections"}], "description": "Students build basic editing workflows for clarity, rhythm, and ethical representation."}]}, {"id": "36eb44a8-acec-407b-9a40-e5f2d3197933", "type": "topic", "title": "Video Shooting and Editing", "description": "Video journalism combines reporting, visual evidence, sequence, sound, and editing judgment. Students learn to shoot and edit credible news video with professional discipline.", "children": [{"id": "ada3dae7-7a4e-4079-9d09-a9eaf11c9127", "type": "subtopic", "title": "Visual reporting in the field", "children": [{"id": "64d80c4a-abdb-470a-a364-7de699229117", "type": "concept", "title": "wide, medium, tight, action, and reaction shots"}, {"id": "336f578e-6e5b-4a03-be85-19ead4c9c140", "type": "concept", "title": "tripod, handheld, and mobile stabilization"}, {"id": "fce2522d-6874-46e0-8270-2e636081cdb6", "type": "concept", "title": "lighting, exposure, focus, and white balance"}], "description": "Students learn to capture sequences that show action, context, and evidence instead of disconnected clips."}, {"id": "96ca20c7-f67f-49c5-825f-590918229775", "type": "subtopic", "title": "Video interviews and sound", "children": [{"id": "2bc8823d-4218-46b8-afa4-04027ce4baa5", "type": "concept", "title": "framing and eyelines"}, {"id": "f4d99ca8-bb98-437b-bc86-b14dc1a304d9", "type": "concept", "title": "lavaliere and shotgun audio"}, {"id": "145e8310-66c7-491c-a15f-977cd81d3cc0", "type": "concept", "title": "b-roll planning and cutaway shots"}], "description": "Students practice setting up interviews that are visually clean and editorially useful."}, {"id": "4ec783c0-a671-4e41-981b-5da31ede2077", "type": "subtopic", "title": "Editing for news clarity", "children": [{"id": "8faaf51f-d1f6-4ff6-8baf-4b1274d5c325", "type": "concept", "title": "sequence editing"}, {"id": "afb8b986-1d5c-4e7c-9c26-ca9e85d7d940", "type": "concept", "title": "lower thirds and captions"}, {"id": "5f71f2aa-459f-4d70-9a67-8adeb7c14a93", "type": "concept", "title": "music, graphics, and manipulation ethics"}], "description": "Students learn to assemble video stories that are accurate, concise, well-paced, and transparent."}]}, {"id": "cc838fc9-4528-426f-991b-1771c1907195", "type": "topic", "title": "Photo Galleries and Slideshows", "description": "Still images remain central to digital storytelling. Students learn to edit photo sequences, write captions, and build visual narratives with context and care.", "children": [{"id": "901889f6-6c25-4bd6-8352-e2f40fd7b19f", "type": "subtopic", "title": "Photo selection and sequencing", "children": [{"id": "251945f8-3b60-4774-9890-112264dc0d90", "type": "concept", "title": "establishing, detail, portrait, action, and closing images"}, {"id": "d83cb4c7-0816-4f29-9e7f-9ce6aef97ede", "type": "concept", "title": "visual rhythm"}, {"id": "9cf0c9c7-d1e0-4f30-a15b-f062bdbd1c61", "type": "concept", "title": "avoiding redundancy"}], "description": "Students learn to choose images that create narrative, variety, and evidence rather than repetition."}, {"id": "601529a2-5863-4095-8592-98c9308a1d22", "type": "subtopic", "title": "Caption and metadata practice", "children": [{"id": "b72f75a5-8f02-48ba-8584-c0b3d8da9daa", "type": "concept", "title": "who, what, when, where, and why"}, {"id": "961f5da9-7efc-4d53-812b-4d89b3f89af5", "type": "concept", "title": "credit lines and rights"}, {"id": "68a805fc-5556-4736-b438-c1070f3770cf", "type": "concept", "title": "alt text and accessibility metadata"}], "description": "Students write captions that identify people, explain context, and avoid unsupported inference."}, {"id": "edc19b13-fda9-47ef-a8db-267d14380ed3", "type": "subtopic", "title": "Visual ethics", "children": [{"id": "157b41d0-a3a2-44a9-8339-4ee9b787a23c", "type": "concept", "title": "toning and cropping boundaries"}, {"id": "f85f010f-106b-4d83-9dfd-51731df611e3", "type": "concept", "title": "graphic images and warnings"}, {"id": "02e76ea1-d312-4747-ac31-6304457b7c3e", "type": "concept", "title": "dignity and privacy"}], "description": "Students examine consent, editing limits, representation, and trauma in photo-driven stories."}]}, {"id": "956b038b-54f6-4fb3-a7b5-5d00d80a7673", "type": "topic", "title": "Web Writing and SEO", "description": "Multimedia packages still need strong web writing. Students learn to write accurate, scannable digital copy and make stories discoverable without sacrificing editorial judgment.", "children": [{"id": "50374519-96da-432f-9993-d0f8686043cf", "type": "subtopic", "title": "Digital writing structure", "children": [{"id": "1dd6665d-9b3b-4eb8-b373-750fc9b488ac", "type": "concept", "title": "headlines, decks, nut grafs, and summaries"}, {"id": "9c17696f-a176-4614-bcfe-6970c133d1fb", "type": "concept", "title": "subheads and short sections"}, {"id": "12fa0ed6-7e4e-4def-a143-b9710812be22", "type": "concept", "title": "links and context modules"}], "description": "Students practice concise web prose that gives readers clear entry points into multimedia work."}, {"id": "51c40eec-7867-437b-8f19-240d8eb4d55e", "type": "subtopic", "title": "SEO for public-service discovery", "children": [{"id": "50c41bce-cf37-4a42-93e2-54b925dd8c3a", "type": "concept", "title": "search intent and keywords"}, {"id": "a0ef2076-816a-45c7-a676-0c2352bc03ee", "type": "concept", "title": "metadata, slugs, and internal links"}, {"id": "120c8dbe-7622-474f-8c68-f3f7ced8dd51", "type": "concept", "title": "evergreen versus breaking-news optimization"}], "description": "Students learn search practices that help audiences find useful reporting honestly."}, {"id": "cccd0769-b3a2-4e19-b89a-d178eeb7ebc6", "type": "subtopic", "title": "Accessibility and usability", "children": [{"id": "16fc4ef0-b08a-43fa-bad9-1652c482b146", "type": "concept", "title": "alt text, captions, and transcripts"}, {"id": "d69e307c-a0f2-4288-9b30-8187f90e1824", "type": "concept", "title": "mobile readability"}, {"id": "29056862-7c95-4f68-bd1e-4ec4d03eb419", "type": "concept", "title": "plain language and inclusive design"}], "description": "Students make web stories readable and usable across devices and abilities."}]}, {"id": "92627a67-803e-40d9-8569-35b6e8b0d63d", "type": "topic", "title": "Interactive Graphics", "description": "Interactive graphics can clarify data, time, geography, process, and choice. Students learn when interactivity improves understanding and how to keep it accurate and accessible.", "children": [{"id": "a2cb719d-e3a8-401a-9aaf-03ea074e8809", "type": "subtopic", "title": "Choosing an interactive form", "children": [{"id": "2433c6a7-963a-4be8-b635-aa696d3c6665", "type": "concept", "title": "timeline stories"}, {"id": "f5e62ab6-8370-4bbc-a0b0-68da5d7ed55f", "type": "concept", "title": "locator maps and annotated maps"}, {"id": "c0bba487-69aa-4c9b-a5f8-0a8f039baa66", "type": "concept", "title": "charts, filters, and lookup tools"}], "description": "Students match story evidence to timelines, maps, charts, databases, calculators, or explainers."}, {"id": "5973df96-d1e9-40f1-8c13-98e28162dd41", "type": "subtopic", "title": "Data and visual accuracy", "children": [{"id": "c647a5bc-2c47-4fea-a210-3cef50fbc2c0", "type": "concept", "title": "source notes and methodology"}, {"id": "13a3af82-291b-4698-abab-927c5ebf0992", "type": "concept", "title": "chart selection and scale"}, {"id": "fb08966e-45d4-4dfa-81e7-2426919613e2", "type": "concept", "title": "uncertainty and missing data"}], "description": "Students learn to clean, verify, label, and explain the data behind graphics."}, {"id": "82167395-54d3-48ac-af6a-32cfe803da92", "type": "subtopic", "title": "User experience and accessibility", "children": [{"id": "7a137856-ff74-4621-9258-0ea0acbefc27", "type": "concept", "title": "responsive layout"}, {"id": "227aceaa-e12c-4779-9ff5-9b1d9dee61e1", "type": "concept", "title": "color contrast and labels"}, {"id": "810d1b42-02af-4c39-b3f0-26df2135c151", "type": "concept", "title": "fallback text and static alternatives"}], "description": "Students design graphics that are clear on mobile, keyboard-friendly, and understandable without decoration."}]}, {"id": "5ec25896-0122-4a30-af1e-64beb64c78d9", "type": "topic", "title": "Social Media Storytelling", "description": "Social platforms are publishing spaces, reporting spaces, and audience spaces. Students learn to adapt journalism for social formats while preserving accuracy and context.", "children": [{"id": "db82e8ec-dbc4-4042-9123-45a358934dea", "type": "subtopic", "title": "Platform-native story forms", "children": [{"id": "07016a98-7495-4473-91d5-1c0f3f3b314e", "type": "concept", "title": "TikTok/Reels explainers"}, {"id": "c4a32055-77b8-4e6c-8cee-2d5c1e9d5a4a", "type": "concept", "title": "Instagram carousels"}, {"id": "e1f2458d-ae05-4e33-b5a2-3c3e3c8279ff", "type": "concept", "title": "threads, cards, and vertical video"}], "description": "Students study how short video, threads, cards, reels, stories, and live posts shape journalism."}, {"id": "b3e64770-b2f6-45d4-b68b-671071e43302", "type": "subtopic", "title": "Verification and context in social publishing", "children": [{"id": "a3302762-2d26-46e6-aa69-8c4a92e07552", "type": "concept", "title": "source checks"}, {"id": "b8273583-629e-4fc6-a04f-817dfcb92b51", "type": "concept", "title": "visual verification"}, {"id": "9c52ebc9-8d40-479b-b52a-34b8719da51c", "type": "concept", "title": "captioning uncertainty"}], "description": "Students learn to avoid spreading unverified material or stripping facts from needed context."}, {"id": "ca92eaab-a049-41ec-9c80-2a09926b352a", "type": "subtopic", "title": "Engagement and moderation", "children": [{"id": "a4450eea-2205-4809-9ee0-e6351b58aa5a", "type": "concept", "title": "calls to action"}, {"id": "35229a1f-e65b-46f6-92a2-ddda7295247f", "type": "concept", "title": "comment triage"}, {"id": "98e39f0f-0cb6-4cf0-94ea-60b2e2b2824f", "type": "concept", "title": "harassment and safety planning"}], "description": "Students connect social publishing to audience questions, community listening, and responsible comment management."}]}, {"id": "f9987b4b-c322-435b-ba75-85767da8ada3", "type": "topic", "title": "Mobile Journalism", "description": "Mobile journalism turns the phone into a reporting, production, editing, and publishing tool. Students learn fast field workflows while maintaining quality and ethics.", "children": [{"id": "98f2aea0-fbef-43cb-897f-57eb0561d591", "type": "subtopic", "title": "Mobile newsgathering", "children": [{"id": "466144c2-b689-4fbd-82c6-bb48a88a16e5", "type": "concept", "title": "mobile video and audio capture"}, {"id": "4bf29cd8-6bee-420e-8fde-62f77c13c091", "type": "concept", "title": "photo, scanner, and note apps"}, {"id": "54915753-9efc-4980-868e-af2214f85efb", "type": "concept", "title": "battery, storage, and backup habits"}], "description": "Students practice using phones for credible field reporting in deadline conditions."}, {"id": "f6dc112a-d226-40f8-818e-ac3f50c4617f", "type": "subtopic", "title": "Mobile editing and publishing", "children": [{"id": "fa072bf4-f233-47e0-8c6b-6a853fe9cadd", "type": "concept", "title": "captioned vertical video"}, {"id": "681ff99a-fdef-4931-9865-48fbfd41426f", "type": "concept", "title": "quick audio clips"}, {"id": "f7324e52-29b3-43db-9d9e-598830a8821a", "type": "concept", "title": "file transfer and cloud organization"}], "description": "Students learn lightweight workflows for quick, accurate publishing from the field."}, {"id": "dffb38ce-eb2e-414a-b0e3-f467bc711a54", "type": "subtopic", "title": "Safety and situational awareness", "children": [{"id": "bad8b339-10ed-469d-84c1-bd0653aa1425", "type": "concept", "title": "location privacy"}, {"id": "22d8d8a1-0ef7-403d-b0c5-215b878be16f", "type": "concept", "title": "crowd and protest awareness"}, {"id": "96edc8f0-9109-44a4-b23b-9ebb4f11f8d6", "type": "concept", "title": "device lock, backups, and metadata"}], "description": "Students learn to manage personal safety, device security, and consent while reporting in public spaces."}]}, {"id": "d6b17dd5-1e85-4863-86ea-15d64c3cec3e", "type": "topic", "title": "Content Management Systems", "description": "A CMS is where multimedia journalism becomes a published product. Students learn how story elements, metadata, embeds, updates, and corrections work together inside newsroom publishing systems.", "children": [{"id": "77452e4f-f148-441c-abe3-36d61db75a8e", "type": "subtopic", "title": "CMS publishing workflow", "children": [{"id": "b61adaf6-3c35-4f15-b0cc-45902424a76e", "type": "concept", "title": "story templates and sections"}, {"id": "9ff1b1fa-485e-43aa-b571-2bf1d1a175b1", "type": "concept", "title": "slugs, tags, thumbnails, and authors"}, {"id": "07cba5c9-c0a4-4772-b028-d806d10de76a", "type": "concept", "title": "preview, scheduling, and revisions"}], "description": "Students learn the basic roles and fields involved in publishing a digital story."}, {"id": "f03e8f22-56fb-428f-85b1-c2f25040da7c", "type": "subtopic", "title": "Embedding and asset management", "children": [{"id": "e0b9b2a0-4342-4672-af9c-dadcacc7e233", "type": "concept", "title": "asset naming and rights"}, {"id": "bff71f99-6654-445d-a80f-fe53beeef38c", "type": "concept", "title": "embed codes and responsive behavior"}, {"id": "85f41820-6787-4630-b4b6-e72fda8bfc81", "type": "concept", "title": "captions, credits, and transcripts"}], "description": "Students learn to organize and publish photos, audio, video, charts, documents, and social embeds reliably."}, {"id": "6cb2aae5-c03f-4b75-9a61-b9c440aa1ace", "type": "subtopic", "title": "Quality assurance and corrections", "children": [{"id": "53907814-13f1-493b-8ab2-763efdb4f8ce", "type": "concept", "title": "link checks and mobile preview"}, {"id": "d754541d-20fd-4bc0-acf2-aec2514f0e2a", "type": "concept", "title": "accessibility checks"}, {"id": "37da5225-3820-423d-aca6-80b353d30803", "type": "concept", "title": "corrections and update notes"}], "description": "Students check packages before and after publication for accuracy, usability, and transparency."}]}, {"id": "343a6212-1089-4865-97dd-d1fad2f86064", "type": "topic", "title": "Multimedia Project Production", "description": "The capstone project asks students to combine reporting, production, design, editing, and distribution into one coherent journalism package.", "children": [{"id": "7a64ca70-b7e5-46dc-9e5f-b4f291c5e478", "type": "subtopic", "title": "Project planning and roles", "children": [{"id": "2efbfa26-dd6c-4587-9f43-a222fa31a659", "type": "concept", "title": "pitch memo and audience promise"}, {"id": "fd71220d-98cc-48c7-bca2-1c14269f4632", "type": "concept", "title": "asset plan and reporting schedule"}, {"id": "00fa89a4-8753-4aa8-adfd-73e8fc1f6539", "type": "concept", "title": "team roles and edit checkpoints"}], "description": "Students scope a multimedia project with deadlines, deliverables, editorial roles, and a realistic production calendar."}, {"id": "1a25acbb-9664-4a6b-bd6e-55b0fd4d4430", "type": "subtopic", "title": "Integrated production", "children": [{"id": "d93e6d12-4aa7-4c8d-9ff5-8bdcccb98e52", "type": "concept", "title": "field production days"}, {"id": "36422ef5-6ae4-4f70-968e-d4c2508fada8", "type": "concept", "title": "rough cuts and package drafts"}, {"id": "0419eef0-a8dc-4d9b-b4dc-de81feb1ef21", "type": "concept", "title": "peer edit and source review"}], "description": "Students produce text, visuals, audio, video, graphics, and social elements so each part adds distinct value."}, {"id": "87ba7271-5044-41a2-b1a9-4900bd6b08ea", "type": "subtopic", "title": "Publication, distribution, and reflection", "children": [{"id": "5429df46-0914-4ffa-b10c-ba228ba68d32", "type": "concept", "title": "launch checklist"}, {"id": "92e2c4ab-2be3-4b31-8f45-70f88b732636", "type": "concept", "title": "social and newsletter plan"}, {"id": "c7776d64-9462-4008-a6b4-a58ef290442f", "type": "concept", "title": "analytics hypothesis and reflective memo"}], "description": "Students finalize a publishable package and explain how it should reach, serve, and inform its audience."}]}], "dbBacked": true}$mmjjson$::jsonb,
